{
  "copy": "<div id="iheni" class="row sectionBlockLayout text-left" style="display: flex; flex-wrap: wrap; margin: 0px; min-height: auto; padding: 8px; background-color: #dbdddd;">
  <div id="ii70z" class="container" style="padding: 0px; display: flex; flex-wrap: wrap;">
    <div id="it2ri" class="col-md-12 columnBlockLayout" style="flex-grow: 1; display: flex; flex-direction: column; min-width: 250px; word-break: break-word; padding: 16px; margin: 60px 0px; background-color: white; border-radius: 10px; box-shadow: rgba(0, 0, 0, 0.1) 0px 2px 4px;">
      <form id="availabilityForm" style="padding: 16px;">
        <div class="week-selector" style="margin-bottom: 16px;">
          <label for="weekStart" style="display: block; font-size: 18px;">Select the start of the week:</label>
          <input type="text" id="weekStart" name="weekStart" autocomplete="off" style="width: 100%; padding: 8px; border: 1px solid #ccc; background-color: #fff; margin-top: 10px; border-radius: 50px;" required placeholder="Please select a week" />
        </div>
        <div id="weekdays" style="margin: 0; padding: 0;">
          <!-- Repeat this block for each day of the week -->
          <div class="day-row" style="margin-bottom: 8px; font-size: 18px;">
            <label style="display: block;">Monday:</label>
            <label class="radio-inline"> <input type="radio" id="mondayAvailable" name="monday" value="available" /> Available </label>
            <label class="radio-inline"> <input type="radio" id="mondayUnavailable" name="monday" value="unavailable" checked /> Unavailable </label>
          </div>
          <!-- Tuesday -->
          <div class="day-row" style="margin-bottom: 8px; font-size: 18px;">
            <label style="display: block;">Tuesday:</label>
            <label class="radio-inline"> <input type="radio" id="tuesdayAvailable" name="tuesday" value="available" /> Available </label>
            <label class="radio-inline"> <input type="radio" id="tuesdayUnavailable" name="tuesday" value="unavailable" checked /> Unavailable </label>
          </div>
          <!-- Wednesday -->
          <div class="day-row" style="margin-bottom: 8px; font-size: 18px;">
            <label style="display: block;">Wednesday:</label>
            <label class="radio-inline"> <input type="radio" id="wednesdayAvailable" name="wednesday" value="available" /> Available </label>
            <label class="radio-inline"> <input type="radio" id="wednesdayUnavailable" name="wednesday" value="unavailable" checked /> Unavailable </label>
          </div>
          <!-- Thursday -->
          <div class="day-row" style="margin-bottom: 8px; font-size: 18px;">
            <label style="display: block;">Thursday:</label>
            <label class="radio-inline"> <input type="radio" id="thursdayAvailable" name="thursday" value="available" /> Available </label>
            <label class="radio-inline"> <input type="radio" id="thursdayUnavailable" name="thursday" value="unavailable" checked /> Unavailable </label>
          </div>
          <!-- Friday -->
          <div class="day-row" style="margin-bottom: 8px; font-size: 18px;">
            <label style="display: block;">Friday:</label>
            <label class="radio-inline"> <input type="radio" id="fridayAvailable" name="friday" value="available" /> Available </label>
            <label class="radio-inline"> <input type="radio" id="fridayUnavailable" name="friday" value="unavailable" checked /> Unavailable </label>
          </div>
          <!-- Saturday -->
          <div class="day-row" style="margin-bottom: 8px; font-size: 18px;">
            <label style="display: block;">Saturday:</label>
            <label class="radio-inline"> <input type="radio" id="saturdayAvailable" name="saturday" value="available" /> Available </label>
            <label class="radio-inline"> <input type="radio" id="saturdayUnavailable" name="saturday" value="unavailable" checked /> Unavailable </label>
          </div>
          <!-- Sunday -->
          <div class="day-row" style="margin-bottom: 8px; font-size: 18px;">
            <label style="display: block;">Sunday:</label>
            <label class="radio-inline"> <input type="radio" id="sundayAvailable" name="sunday" value="available" /> Available </label>
            <label class="radio-inline"> <input type="radio" id="sundayUnavailable" name="sunday" value="unavailable" checked /> Unavailable </label>
          </div>
        </div>
        <button
          type="submit"
          id="itecsb"
          style="
          border-color: #006680;
          border-radius: 2px;
          margin-top: 10px;
          font-family: Arial;
          font-weight: 600;
          font-size: 15px;
          padding: 6px 20px;
          width: fit-content;
          border-style: solid;
          background-color: #006680;
          color: #FFFFFF;"
        >
          Submit
        </button>
      </form>
    </div>
  </div>
</div>

{% if request.params['contactid']%}
{% assign contactid = request.params['contactid']  %}
{% endif %}

<style>
  .ui-datepicker .ui-state-hover {
    background: none !important;
    border: none !important;
    cursor: default !important;
  }

  .ui-datepicker .ui-state-active,
  .ui-datepicker .ui-state-highlight {
    background: none !important;
    border: none !important;
  }

  .ui-datepicker-calendar a:hover {
    text-decoration: none !important;
  }


  .ui-datepicker .ui-datepicker-prev span,
  .ui-datepicker .ui-datepicker-next span {
    color: #0000 !important;
  }
  .ui-datepicker .ui-datepicker-prev:hover,
  .ui-datepicker .ui-datepicker-next:hover {
    background-color: #83E8F2 !important;
  }
  .ui-datepicker .ui-datepicker-calendar tr:hover {
    background-color: #83E8F2 !important;
  }
  .radio-inline {
    margin-left: 5px;
    font-family: wf_segoe-ui, 'Segoe UI', Frutiger, 'Frutiger Linotype', 'Dejavu Sans', 'Helvetica Neue', 'Arial', sans-serif;
    margin-right: 10px; /* Adjust spacing as needed */
  }
</style>
<script>
  $(document).ready(function() {
    var startDate, endDate;

    // Function to update tooltips for each day of the week
    function updateTooltips(startDate) {
      var currentDate = new Date(startDate);
      $('#weekdays .day-row').each(function(index, element) {
        var day = $(element).find('input[type="radio"]').first().attr('name');
        var formattedDate = $.datepicker.formatDate('MM d, yy', currentDate);
        $(element).find('label').attr('title', formattedDate); // Applying tooltip to the label
        currentDate.setDate(currentDate.getDate() + 1);
      });
    }

    // Initialize the datepicker
    $("#weekStart").datepicker({
      showOtherMonths: true,
      selectOtherMonths: true,
      showWeek: true,
      firstDay: 1,
      changeMonth: true,
      changeYear: true,
      onSelect: function(dateText, inst) {
        var date = $(this).datepicker('getDate');
        startDate = new Date(date.getFullYear(), date.getMonth(), date.getDate() - date.getDay() + 1);
        endDate = new Date(startDate);
        endDate.setDate(startDate.getDate() + 6);
        $(this).val($.datepicker.formatDate('yy-mm-dd', startDate) + ' - ' + $.datepicker.formatDate('yy-mm-dd', endDate));
        updateTooltips(startDate);
      },
      beforeShowDay: function(date) {
        var cssClass = '';
        if(date >= startDate && date <= endDate) {
          cssClass = 'selected-week'; // this class can be styled in the customStyles
        }
        return [true, cssClass];
      }
    });

    // Handle the form submission
    $("#availabilityForm").submit(function(e) {
      e.preventDefault();

      var availabilityArray = [];
      var allFilled = true;
      var currentDate = new Date(startDate);

      var days = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];

      days.forEach(function(day) {
        var isAvailable = $('#' + day + 'Available').is(':checked');
        if (!$('input[name="' + day + '"]:checked').val()) {
          alert('Please select an option for ' + day + '.');
          allFilled = false;
          return false; // Break out of the forEach loop
        }
        availabilityArray.push({
          availability: isAvailable,
          day: day,
          date: $.datepicker.formatDate('yy-mm-dd', currentDate)
        });
        currentDate.setDate(currentDate.getDate() + 1);
      });

      if (allFilled) {
        console.log(availabilityArray);
        ProcessSubmit(availabilityArray);
      }
    });
  });

  function ProcessSubmit(availabilityArray) {
    // Get the current page's URL
    var currentPageUrl = window.location.href;
    // Extract the base URL
    var baseUrl = currentPageUrl.split('/').slice(0, 3).join('/');
    // Define the relative path to your API endpoint
    //shift candidate availability insert
    var relativePath = "_api/cloudflow/v1.0/trigger/a6f9c9af-c850-ef11-a316-002248cb952b";
    // Construct the full URL by concatenating the base URL and the relative path
    var flowUrl = baseUrl + "/" + relativePath;
    console.log('flowUrl ', flowUrl);

    var flowData = {
      requestarray: JSON.stringify(availabilityArray),
      contactid: `{{contactid}}`
    };

    console.log(JSON.stringify(flowData));

    shell.ajaxSafePost({
        type: "POST",
        contentType: "application/json",
        url: flowUrl,
        data: JSON.stringify({ "eventData": JSON.stringify(flowData) }),
        global: false
    })
    .done(function(response) {
        console.log('Response:', response);
        // Parse the response
        var result = JSON.parse(response);
        if (result.processed != "True") {
            // Display specific error message
            alert(result.errormessage || 'Process failed. Please try again.');
        } else {
            console.log('Processed successfully');

            var partialurl = "/shifts/candidateavailability/?contactid={{contactid}}";
            var nextPageUrl = new URL(window.location.origin + partialurl);
            window.location.href = nextPageUrl.toString();
        }
    })
    .fail(function(jqXHR, textStatus, errorThrown) {
        console.error('Error: ', textStatus, ', Details: ', errorThrown);
        console.error('Response: ', jqXHR.responseText);
    });
  }
</script>
